        $this->addSql("INSERT INTO `prescriptionregl` (`ID_PRESCRIPTIONREGL`, `PRESCRIPTIONREGL_TYPE`, `PRESCRIPTIONREGL_LIBELLE`, `PRESCRIPTIONREGL_VISIBLE`) VALUES
            (1, 1, 'Les constructeurs, propriétaires et exploitants des établissements recevant du public sont tenus, tant au moment de la construction qu''au cours de l''exploitation, de respecter les mesures de prévention et de sauvegarde propres à assurer la sécurité des personnes ; ces mesures sont déterminées compte tenu de la nature de l''exploitation, des dimensions des locaux, de leur mode de construction, du nombre de personnes pouvant y être admises et de leur aptitude à se soustraire aux effets d''un incendie.', 1),
            (2, 1, 'Respecter les engagements du maître d''ouvrage dans sa notice de sécurité.', 1),
            (3, 1, 'Veiller à ce que les travaux qui feraient courir un danger quelconque au public ou qui apporteraient une gêne à son évacuation soient effectués en dehors de sa présence.', 1),
            (4, 1, 'Les appareils ou équipements doivent être conformes soit aux normes françaises, soit aux normes européennes harmonisées, soit aux normes ou spécifications techniques d’autres états de l’Union Européenne reconnues conformément à l’article GN 14 du règlement de sécurité.', 1),
            (5, 1, 'Solliciter le passage de la commission de sécurité à l''issue des travaux de cet établissement. Cette demande doit être formulée au Maire de la commune concernée qui avisera le secrétariat de la commission et ce, au moins 1 mois avant la date fixée.', 1),
            (7, 2, 'Les constructeurs, propriétaires et exploitants des établissements recevant du public sont tenus, tant au moment de la construction qu''au cours de l''exploitation, de respecter les mesures de prévention et de sauvegarde propres à assurer la sécurité des personnes ; ces mesures sont déterminées compte tenu de la nature de l''exploitation, des dimensions des locaux, de leur mode de construction, du nombre de personnes pouvant y être admises et de leur aptitude à se soustraire aux effets d''un incendie.', 0),
            (8, 2, 'Les constructeurs, installateurs et exploitants sont tenus, chacun en ce qui le concerne, de s''assurer que les installations ou équipements sont établis, maintenus et entretenus en conformité avec les dispositions de la présente réglementation. A cet effet, ils font respectivement procéder pendant la construction et périodiquement en cours d''exploitation aux vérifications nécessaires par les organismes ou personnes agréés dans les conditions fixées par arrêté du Ministre de l''Intérieur. Le contrôle exercé par l''administration ou par les commissions de sécurité ne les dégage pas des responsabilités qui leur incombent personnellement.', 1),
            (9, 2, 'Tenir à jour le registre de sécurité sur lequel sont reportés les renseignements indispensables à la bonne marche du service de sécurité et, en particulier :\r\n- l''état du personnel chargé du service d''incendie ;\r\n- les diverses consignes, générales et particulières, établies en cas d''incendie, y compris les consignes d''évacuation prenant en compte les différents types de handicap ; \r\n- les dates des divers contrôles et vérifications ainsi que les observations auxquelles ceux-ci ont donné lieu ;\r\n- les dates des travaux d''aménagement et de transformation, leur nature, les noms du ou des entrepreneurs et, s''il y a lieu, de l''architecte ou du technicien chargé de surveiller les travaux', 1)
        ");
